/**
 * Init Command Prompt Utilities
 * Handles all interactive prompts for agent initialization
 */
import inquirer from "inquirer";
import chalk from 'chalk';
/**
 * Prompts user to choose between existing or new agent.
 *
 * @returns Selected choice ('existing' or 'create')
 */
export async function promptAgentChoice() {
    const { agentChoice } = await inquirer.prompt([
        {
            type: "list",
            name: "agentChoice",
            message: "How would you like to set up your AI Agent?",
            choices: [
                { name: "Use one of your existing agents", value: "existing" },
                { name: "Create a new agent", value: "create" }
            ]
        }
    ]);
    return agentChoice;
}
/**
 * Prompts user to select an organization from available options.
 *
 * @param orgs - Array of organizations to choose from
 * @returns Selected organization
 */
export async function promptOrganizationSelection(orgs) {
    const orgChoices = orgs.map((org) => ({
        name: org.registeredName || org.name || 'Unknown Organization',
        value: org
    }));
    const { selectedOrg } = await inquirer.prompt([
        {
            type: "list",
            name: "selectedOrg",
            message: "Select an organization:",
            choices: orgChoices
        }
    ]);
    return selectedOrg;
}
/**
 * Prompts user to select an agent from an organization.
 *
 * @param org - Organization containing agents
 * @returns Selected agent
 */
export async function promptAgentSelection(org) {
    if (!org.agents || org.agents.length === 0) {
        throw new Error("No agents found in the selected organization.");
    }
    const agentChoices = org.agents.map((agent) => ({
        name: agent.name,
        value: agent
    }));
    const { selectedAgent } = await inquirer.prompt([
        {
            type: "list",
            name: "selectedAgent",
            message: "Select an agent:",
            choices: agentChoices
        }
    ]);
    return selectedAgent;
}
/**
 * Prompts for metadata fields required by the agent type.
 *
 * @param requiredFields - Array of required metadata field names
 * @returns Object containing collected metadata
 */
export async function promptMetadataCollection(requiredFields) {
    const metadata = {};
    for (const field of requiredFields) {
        const { [field]: value } = await inquirer.prompt([
            {
                type: "input",
                name: field,
                message: `Enter ${field}:`,
                validate: (input) => input.trim().length > 0 || `${field} is required`
            }
        ]);
        metadata[field] = value;
    }
    return metadata;
}
/**
 * Prompts for agent name only.
 * Persona configuration is done via dashboard or code.
 *
 * @returns Agent name
 */
export async function promptAgentName() {
    const { agentName } = await inquirer.prompt([
        {
            type: "input",
            name: "agentName",
            message: "Enter agent name:",
            validate: (input) => input.trim().length > 0 || "Agent name is required"
        }
    ]);
    return agentName;
}
/**
 * Prompts user to select an LLM model from the list of approved models.
 * Presents a searchable list grouped by provider. The user can type to filter.
 * Returns undefined if the user skips (uses platform default).
 *
 * @param models - Pre-fetched array of approved models from the API
 * @returns Selected model code (e.g. 'openai/gpt-4o') or undefined if skipped
 */
export async function promptModelSelection(models) {
    if (models.length === 0) {
        return undefined;
    }
    const SKIP_VALUE = '__skip__';
    // Group models by provider for display
    const providers = [...new Set(models.map(m => m.provider))].sort();
    const choices = [
        { name: 'Skip — use platform default', value: SKIP_VALUE },
    ];
    for (const provider of providers) {
        const providerModels = models.filter(m => m.provider === provider);
        choices.push(new inquirer.Separator(`  ── ${provider} ──`));
        for (const m of providerModels) {
            choices.push({
                name: `${chalk.bold(m.code)}  ${chalk.gray(m.description)}`,
                value: m.code,
                short: m.code,
            });
        }
    }
    const { selectedModel } = await inquirer.prompt([
        {
            type: 'list',
            name: 'selectedModel',
            message: 'LLM model: (type to filter)',
            choices,
            pageSize: 14,
        }
    ]);
    return selectedModel === SKIP_VALUE ? undefined : selectedModel;
}
